import { z } from "zod";

// Exercise lists (Person 1, D72): practice questions on a topic the class struggles with, generated by Claude from the
// teacher's book. Built from topics and pages only: no student's name or words go into the prompt or the document.

export const ExerciseKind = z.enum(["choice", "open"]);
export type ExerciseKind = z.infer<typeof ExerciseKind>;

export const Exercise = z.object({
  id: z.string(),
  kind: ExerciseKind,
  prompt: z.string(),
  /** Exactly 4 options for "choice"; absent for "open". */
  options: z.array(z.string()).optional(),
  /** The right option (choice) or the expected answer (open). Only in the teacher's copy. */
  answer: z.string(),
  /** Why it is right, with the page of the book when there is one. Only in the teacher's copy. */
  explanation: z.string(),
  page: z.number().int().nullable(),
});
export type Exercise = z.infer<typeof Exercise>;

export const ExerciseListStatus = z.enum(["generating", "ready", "failed"]);
export type ExerciseListStatus = z.infer<typeof ExerciseListStatus>;

export const ExerciseList = z.object({
  id: z.string(),
  title: z.string(),
  concept: z.string(),
  concept_key: z.string(),
  /** The book and lesson the questions come from (null when the gaps point to no material). */
  material_id: z.string().nullable(),
  material_title: z.string().nullable(),
  lesson_id: z.string().nullable(),
  lesson_title: z.string().nullable(),
  pages: z.tuple([z.number().int(), z.number().int()]).nullable(),
  grade_level: z.string(),
  /** The open gaps the list was made for (traceability; the UI shows only how many students). */
  gap_ids: z.array(z.string()),
  student_count: z.number().int(),
  status: ExerciseListStatus,
  error: z.string().nullable(),
  exercises: z.array(Exercise),
  model: z.string().nullable(),
  prompt_version: z.string(),
  created_at: z.string(),
  updated_at: z.string(),
});
export type ExerciseList = z.infer<typeof ExerciseList>;
export type ExerciseListDraft = Omit<ExerciseList, "id" | "created_at" | "updated_at">;

/** `POST /api/exercise-lists`: the topic and the open gaps it groups (the intervention card sends them). */
export const CreateExerciseListBody = z.object({
  concept: z.string().trim().min(1).max(120),
  gap_ids: z.array(z.string()).min(1).max(100),
});
export type CreateExerciseListBody = z.infer<typeof CreateExerciseListBody>;

/** Storage of the generated lists (collection `exercise_lists`). Mongo and in-memory implementations in @mento/db. */
export interface ExerciseListStore {
  create(draft: ExerciseListDraft): Promise<ExerciseList>;
  update(id: string, patch: Partial<ExerciseListDraft>): Promise<ExerciseList | null>;
  get(id: string): Promise<ExerciseList | null>;
  /** Newest first. */
  list(): Promise<ExerciseList[]>;
  delete(id: string): Promise<boolean>;
}
